import random
from collections import deque

def solve_optimal(nums, limit):
    maxq, minq = deque(), deque()
    left = 0
    best = 0
    for right, x in enumerate(nums):
        while maxq and nums[maxq[-1]] <= x:
            maxq.pop()
        maxq.append(right)
        while minq and nums[minq[-1]] >= x:
            minq.pop()
        minq.append(right)
        while nums[maxq[0]] - nums[minq[0]] > limit:
            left += 1
            if maxq[0] < left:
                maxq.popleft()
            if minq[0] < left:
                minq.popleft()
        best = max(best, right - left + 1)
    return best

def solve_brute(nums, limit):
    best = 0
    for i in range(len(nums)):
        for j in range(i, len(nums)):
            window = nums[i:j + 1]
            if max(window) - min(window) <= limit:
                best = max(best, j - i + 1)
    return best

def gen(rng, size):
    low, high = {"tiny": (1, 4), "small": (1, 12), "large": (30, 80)}[size]
    n = rng.randint(low, high)
    return [[rng.randint(0, 30) for _ in range(n)], rng.randint(0, 15)]

def validate(args):
    nums, limit = args
    return 1 <= len(nums) <= 1000 and limit >= 0 and all(0 <= x <= 10**9 for x in nums)
